func recordMigrationSkipOrFailure(ctx context.Context, result *migrateResult, cpID id.CheckpointID, err error) {
	switch {
	case errors.Is(err, errAlreadyMigrated):
		logCheckpointMigrationSkip(ctx, cpID, "already in v2", err)
